hooks.command:
H="$HOME"/.modernize/psa/tools/hooks/current/scripts/gates/pre_tool_dispatch.py; I=$(cat); if [ -x "$H" ]; then printf %s "$I" | "$H"; c=$?; why="异常退出（退出码 ${c}：门导入失败、出错、超时或崩溃）"; else c=127; why="入口缺失或不可执行（${H}）"; fi; [ "$c" = 0 ] || [ "$c" = 2 ] && exit "$c"; L="$HOME"/.modernize/psa/tools/hooks/gate_failures.log; if printf %s "$I" | /usr/bin/python3 -I -c 'import json,os,re,sys
p=json.load(sys.stdin)
if p.get("tool_name","Bash") not in ["Bash", "Monitor", "mcp__terminal__run_in_terminal", "mcp__Claude_Browser__preview_start"]:sys.exit(0)
if p.get("tool_name")=="Monitor" and "command" not in p.get("tool_input",{}):sys.exit(0)
c=p["tool_input"]["command"].lower()
t=[]
for f in [os.path.expanduser("~/.modernize/psa/tools/hooks/current/scripts/gates/prod_targets.json"),os.path.join(os.environ.get("CLAUDE_PROJECT_DIR","/nonexistent"),"scripts/gates/prod_targets.json")]:
 try:t+=[x.strip().lower() for g in json.load(open(f))["targets"] for x in g["patterns"] if len(x.strip())>=6]
 except Exception:pass
sys.exit(1 if not t or any(x in c for x in t) else 0)'; then echo "【钩子告警】生产写门${why}；保守预筛判定这条命令不涉及生产，放行；请 one-ops 执行 scripts/gates/install.sh 修复" >&2; printf "%s\t放行\t%s\n" "$(date +%FT%T)" "$why" 2>/dev/null >>"$L"; exit 0; fi; echo "生产写门${why}；保守预筛不能排除这条命令涉及生产，按拒绝处理；请把报错转 one-ops" >&2; printf "%s\t拒绝\t%s\n" "$(date +%FT%T)" "$why" 2>/dev/null >>"$L"; exit 2
